∀ {Γ : Set Breakdown.Symmetry} {P : ℝ} {v : ℝ → Breakdown.Space → Breakdown.Space}
  {G : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {H : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
  {g : ℝ → Breakdown.Space → Breakdown.Space},
  Breakdown.IsPerturbation Γ P v G H g →
    ∀ (n : ℕ) (σ : ℝ) (y : Breakdown.Space),
      Breakdown.divergenceAt (Breakdown.Coercive.Internal.SmoothApprox.mollify n v σ) y = 0

∀ {Γ : Set Breakdown.Symmetry} {P : ℝ} {v : ℝ → Breakdown.Space → Breakdown.Space}
  {G : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {H : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
  {g : ℝ → Breakdown.Space → Breakdown.Space},
  Breakdown.IsPerturbation Γ P v G H g →
    Filter.Tendsto
      (fun n =>
        Breakdown.periodLIntegral fun σ y =>
          ‖Breakdown.Coercive.Internal.SmoothApprox.mollify n v σ y - v σ y‖ ^ 2 / (1 + ‖y‖) ^ 2)
      Filter.atTop (nhds 0)

∀ {Γ : Set Breakdown.Symmetry} {P : ℝ} {v : ℝ → Breakdown.Space → Breakdown.Space}
  {G : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {H : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
  {g : ℝ → Breakdown.Space → Breakdown.Space},
  Breakdown.IsPerturbation Γ P v G H g →
    ∀ (n : ℕ), Breakdown.Coercive.IsSmoothPerturbation P (Breakdown.Coercive.Internal.SmoothApprox.mollify n v)

∀ {Γ : Set Breakdown.Symmetry} {P : ℝ} {v : ℝ → Breakdown.Space → Breakdown.Space}
  {G : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {H : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
  {g : ℝ → Breakdown.Space → Breakdown.Space} {u : ℕ → ℝ → Breakdown.Space → Breakdown.Space},
  Breakdown.IsPerturbation Γ P v G H g →
    Breakdown.Coercive.IsSmoothApproximation P v G H g u →
      (Breakdown.periodLIntegral fun σ y => ‖v σ y‖ ^ 2 / (1 + ‖y‖) ^ 2) < ⊤

