∀ {C : Type} {nE nM : ℕ} {m : Breakdown.PieceWeights C nE nM} {P : ℝ} {h : Breakdown.HarmonicBounds}
  {w : Breakdown.Space → ℝ} {W v : ℝ → Breakdown.Space → Breakdown.Space}
  {G : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {H : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
  {w₀ epsSup epsGradSup ratio : ℝ},
  m.IsAdmissible P h w W w₀ epsSup epsGradSup ratio →
    (ContDiff ℝ 2 fun z => W z.1 z.2) →
      MeasureTheory.AEStronglyMeasurable (fun z => v z.1 z.2) MeasureTheory.volume →
        MeasureTheory.AEStronglyMeasurable (fun z => G z.1 z.2) MeasureTheory.volume →
          MeasureTheory.AEStronglyMeasurable (fun z => H z.1 z.2) MeasureTheory.volume →
            AEMeasurable (fun z => Breakdown.Coercive.pieceBlock m W v G H z.1 z.2) MeasureTheory.volume

∀ {C : Type} {m : Breakdown.ModeWeights C} {P : ℝ} {b : Breakdown.FlowBounds C} {w : Breakdown.Space → ℝ}
  {W : ℝ → Breakdown.Space → Breakdown.Space} {w₀ epsSup epsGradSup ratio : ℝ}
  {v : ℝ → Breakdown.Space → Breakdown.Space},
  Breakdown.Coercive.SmoothEpsInternal.EpsSetting m P b w W w₀ epsSup epsGradSup ratio v →
    Breakdown.Coercive.IsSmoothPerturbation P v

∀ {Γ : Set Breakdown.Symmetry} {P : ℝ} {v : ℝ → Breakdown.Space → Breakdown.Space}
  {G : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {H : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
  {g : ℝ → Breakdown.Space → Breakdown.Space},
  Breakdown.IsPerturbation Γ P v G H g →
    ∀ (n j : ℕ),
      1 ≤ j →
        (Breakdown.periodLIntegral fun σ y =>
            ‖iteratedFDeriv ℝ j (Breakdown.Coercive.Internal.SmoothApprox.mollify n v σ) y‖ ^ 2) <
          ⊤

∀ {C : Type} {m : Breakdown.ModeWeights C} {P : ℝ} {b : Breakdown.FlowBounds C} {w : Breakdown.Space → ℝ}
  {W : ℝ → Breakdown.Space → Breakdown.Space} {w₀ epsSup epsGradSup ratio : ℝ}
  {v : ℝ → Breakdown.Space → Breakdown.Space},
  Breakdown.Coercive.SmoothEpsInternal.EpsSetting m P b w W w₀ epsSup epsGradSup ratio v →
    ∀ (σ : ℝ) (y : Breakdown.Space), Breakdown.divergenceAt (W σ) y = 0

Breakdown.Coercive.SolenoidalModeHolds →
  ∀ {C : Type} {nE nM : ℕ} {m : Breakdown.PieceWeights C nE nM} {v : ℝ → Breakdown.Space → Breakdown.Space}
    {G : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
    {H : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
    {M₁ M₂ : ℝ → Breakdown.Space → Breakdown.Space},
    m.IsMultiplierField v G H M₁ → m.IsMultiplierField v G H M₂ → Breakdown.periodNorm M₁ = Breakdown.periodNorm M₂

∀ {C : Type} {nE nM : ℕ} {m : Breakdown.PieceWeights C nE nM} {P : ℝ} {h : Breakdown.HarmonicBounds}
  {w : Breakdown.Space → ℝ} {Γ : Set Breakdown.Symmetry} {W : ℝ → Breakdown.Space → Breakdown.Space}
  {w₀ epsSup epsGradSup ratio : ℝ},
  m.IsAdmissible P h w W w₀ epsSup epsGradSup ratio →
    (∃ B, ∀ (y : Breakdown.Space), w y ≤ B) →
      ∀ {v : ℝ → Breakdown.Space → Breakdown.Space} {G : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
        {H : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
        {g : ℝ → Breakdown.Space → Breakdown.Space},
        Breakdown.IsPerturbation Γ P v G H g →
          (Breakdown.periodLIntegral fun σ y => ‖Breakdown.secondDerivTrace (H σ y)‖ ^ 2).toReal ≤
              Breakdown.weightedEnergy w G H ∧
            w₀ * (Breakdown.periodLIntegral fun σ y => Breakdown.matSq (G σ y)).toReal ≤ Breakdown.weightedEnergy w G H

∀ {Γ : Set Breakdown.Symmetry} {P : ℝ} {v : ℝ → Breakdown.Space → Breakdown.Space}
  {G : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {H : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
  {g : ℝ → Breakdown.Space → Breakdown.Space},
  Breakdown.IsPerturbation Γ P v G H g → (Breakdown.periodLIntegral fun σ y => ‖v σ y‖ ^ 2 * (1 / (1 + ‖y‖) ^ 2)) < ⊤

∀ {C : Type} {m : Breakdown.ModeWeights C} {P : ℝ} {b : Breakdown.FlowBounds C} {w : Breakdown.Space → ℝ}
  {W : ℝ → Breakdown.Space → Breakdown.Space} {w₀ epsSup epsGradSup ratio : ℝ}
  {v : ℝ → Breakdown.Space → Breakdown.Space},
  Breakdown.Coercive.SmoothEpsInternal.EpsSetting m P b w W w₀ epsSup epsGradSup ratio v →
    ContDiff ℝ 2 fun z => W z.1 z.2

∀ {Γ : Set Breakdown.Symmetry} {P : ℝ} {v : ℝ → Breakdown.Space → Breakdown.Space}
  {G : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space}
  {H : ℝ → Breakdown.Space → Breakdown.Space →L[ℝ] Breakdown.Space →L[ℝ] Breakdown.Space}
  {g : ℝ → Breakdown.Space → Breakdown.Space},
  Breakdown.IsPerturbation Γ P v G H g →
    ∀ (n : ℕ) (σ : ℝ) (y : Breakdown.Space),
      Breakdown.secondDerivField (Breakdown.Coercive.Internal.SmoothApprox.mollify n v) σ y =
        MeasureTheory.convolution (Breakdown.Coercive.Internal.SmoothApprox.kernel n)
          (Breakdown.Coercive.Internal.SmoothApprox.joint H) (ContinuousLinearMap.lsmul ℝ ℝ) MeasureTheory.volume (σ, y)

